/** Decode the bundled photo for [slug], or null if there is none. */
fun photoBitmap(slug: String): Bitmap? {
    val encoded = PHOTO_BASE64[slug] ?: return null
    return try {
        val bytes = Base64.decode(encoded, Base64.DEFAULT)
        BitmapFactory.decodeByteArray(bytes, 0, bytes.size)
    } catch (_: Exception) {
        null
    }
}

/** True when a bundled photo exists for [slug]. */
fun hasPhoto(slug: String): Boolean = PHOTO_BASE64.containsKey(slug)
